import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
references = json.loads(Path('reference-targets.json').read_text())
answers = []


def add(number, xml, reason, review, removed=None, benefit=None):
    source = next(a for a in sources if a['number'] == number)
    obj = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    obj.update(proposed_xml=xml.strip(), reason=reason, review_notes=review, status='rewrite_draft')
    if removed:
        obj.update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if benefit:
        obj['benefit_review'] = benefit
    answers.append(obj)


add('L225-1-5', '''
<p>Sous réserve des dispositions particulières qui prévoient une autre affectation, le produit des majorations de retard et des pénalités dues par les redevables est réparti entre les branches du régime général de sécurité sociale. Un arrêté du ministre chargé de la sécurité sociale fixe les conditions de cette répartition.</p>
''',
    "Droit constant : la règle d'affectation est dissociée de son mode de fixation. Le caractère subsidiaire de cette répartition est conservé. L'article ne crée ni majoration ni pénalité : son abrogation ne supprimerait pas ces charges et laisserait leur produit sans règle générale d'affectation. Leur éventuel allègement doit viser leurs véritables faits générateurs, sans retirer ici une règle nécessaire à la comptabilité des branches.",
    "Une seule règle d'affectation, avec maintien des régimes particuliers et de l'arrêté ministériel. La note du 23 décembre 2021 reste applicable aux cotisations et contributions dues pour les périodes d'activité courant à compter du 1er janvier 2022 ; elle ne fixe aucune date de la réforme proposée. Aucune dette nouvelle, compensation ni pénalité de remplacement n'est instituée. Les suppressions de prélèvements décidées ailleurs ne sont pas remises en cause par cette affectation.")

add('L225-2', '''
<p>L'Agence centrale des organismes de sécurité sociale est un établissement public national à caractère administratif, doté de la personnalité juridique et de l'autonomie financière. Les autorités compétentes de l'État exercent leur contrôle sur cet établissement.</p>
''',
    "Droit constant : le statut, la personnalité juridique, l'autonomie financière et le contrôle de l'État sont énoncés directement. Ce socle identifie la personne responsable de la trésorerie sociale ; il n'impose aucun dossier, prélèvement accessoire ou autorisation particulière susceptible d'être retiré. Supprimer le contrôle sans distinguer ses objets affaiblirait la responsabilité financière de l'établissement.",
    "Les quatre qualifications cumulatives de l'agence sont maintenues, sans transfert de compétences ni changement de personnalité morale. La réécriture ne crée aucun contrôle ou agrément supplémentaire et ne préjuge pas de l'allègement de procédures particulières dans leurs articles propres.")

add('L225-3', '''
<p>Un conseil d'administration de trente membres administre l'Agence centrale des organismes de sécurité sociale. Il comprend :</p>
<p>1° Treize représentants des assurés sociaux, désignés par les organisations syndicales de salariés interprofessionnelles représentatives au niveau national ;</p>
<p>2° Treize représentants des employeurs et des travailleurs indépendants, répartis comme suit :</p>
<p>- dix représentants des employeurs, désignés par les organisations professionnelles nationales d'employeurs représentatives ;</p>
<p>- trois représentants des travailleurs indépendants, désignés par les institutions ou organisations professionnelles des travailleurs indépendants représentatives au niveau national ;</p>
<p>3° Quatre personnes qualifiées dans les domaines d'activité des unions de recouvrement, désignées par l'autorité compétente de l'État.</p>
<p>Participent aussi au conseil, avec voix consultative, un représentant que l'assemblée générale du Conseil de la protection sociale des travailleurs indépendants désigne en son sein et trois représentants du personnel élus dans les conditions fixées par décret.</p>
''',
    "Droit constant : la composition et les modes de désignation sont réécrits en distinguant les trente administrateurs et les participants consultatifs. Le paritarisme, la représentation des indépendants et celle du personnel justifient le maintien de ces règles de gouvernance. Aucun prélèvement ni circuit déclaratif distinct n'est institué par cet article ; réduire les sièges sans réformer leur représentation ne supprimerait pas une charge identifiée.",
    "Contrôle arithmétique : 13 + 13 + 4 = 30 ; le deuxième groupe comprend 10 + 3 membres. Le représentant du Conseil de la protection sociale des travailleurs indépendants et les trois élus du personnel restent consultatifs et ne sont pas ajoutés aux trente administrateurs. Les sept alinéas de contenu sont conservés, ainsi que l'habilitation réglementaire pour l'élection. La note source limitée à un point ne contient aucune transition exploitable.")

add('L225-4', '''
<p>Les caisses de sécurité sociale communiquent à l'Agence centrale des organismes de sécurité sociale les informations nécessaires à la mission que lui confie l'article L. 225-1. Elles sont dispensées de transmettre à nouveau les informations exactes et à jour dont l'agence dispose déjà ou auxquelles elle a légalement accès. Aucune attestation distincte du même contenu ne peut être exigée à la place de cette nouvelle transmission. Seuls les éléments manquants ou modifiés et les explications nécessaires peuvent être demandés.</p>
<p>Cette dispense s'applique aux demandes de communication formulées à compter de l'entrée en vigueur de la loi, y compris lorsqu'elles concernent des périodes antérieures. Les transmissions déjà accomplies n'ont pas à être renouvelées. Les règles de secret, de sécurité et de protection des données demeurent applicables.</p>
''',
    "Réforme de fond : suppression des communications répétées d'informations exactes et à jour déjà disponibles, sans attestation ou déclaration de remplacement. La communication résiduelle reste limitée aux besoins de la gestion commune de trésorerie prévue à L. 225-1. La mission de suivi des branches justifie de conserver les données manquantes, mises à jour et explications nécessaires, avec leurs protections.",
    "L. 225-1 a été lu dans le corpus : gestion commune, individualisation et prévisions de trésorerie de chaque branche. La dispense ne ferme aucune de ces missions et ne donne aucun accès nouveau à des données protégées. Les contrôles d'exactitude et les explications restent possibles ; une demande identique ne peut contourner la dispense. Coordination des circuits de transmission de trésorerie à prévoir sans recréer de dépôt ni de certification. Application aux demandes nouvelles, sans effacer les conséquences des anciennes obligations déjà exigibles.",
    ["La nouvelle transmission des informations exactes et à jour déjà détenues par l'agence ou légalement accessibles, ainsi que l'attestation distincte qui en répéterait le contenu, ne sont plus exigibles."])

add('L225-6', '''
<p>I. - Les branches du régime général mentionnées à l'article L. 200-2 couvrent les charges de gestion administrative de l'Agence centrale des organismes de sécurité sociale, dans les conditions fixées par arrêté interministériel.</p>
<p>II. - Le solde qui résulte, pour l'agence, de la prise en charge prévue au 7° bis de l'article L. 225-1-1, après prise en compte des recettes attribuées à ce titre, ainsi que des dispositions des troisième à neuvième alinéas du 5° du même article, est affecté aux branches mentionnées à l'article L. 200-2. Un arrêté des ministres chargés du budget et de la sécurité sociale répartit ce solde en fonction des soldes prévisionnels de ces branches. Le solde qui résulte de la prise en charge prévue au 7° de l'article L. 225-1-1, après prise en compte des recettes attribuées à ce titre, est affecté à la branche mentionnée au 3° de l'article L. 200-2. Un arrêté conjoint des ministres chargés de la sécurité sociale et du budget répartit les recettes affectées aux dépenses de l'agence prévues aux 7° et 7° bis de l'article L. 225-1-1, en tenant compte du niveau des compensations prévues à ces subdivisions.</p>
''',
    "Droit constant : les charges administratives et les deux soldes de compensation sont distingués, avec maintien de leurs règles d'affectation. Il s'agit de transferts entre organismes, non d'une cotisation autonome à supprimer. Leur suppression fragiliserait la prise en charge des allègements ; aucun financement ni prélèvement de remplacement n'est créé. Les réformes du contrat unique s'appliquent aux règles de cotisation concernées, sans modifier artificiellement cette répartition.",
    "L. 200-2 lu : cinq branches ; son 3° désigne vieillesse et veuvage. L. 225-1-1 lu en source et en proposition : conserver la distinction entre 7° (compensation de cotisations effectivement recouvrées pour les régimes visés) et 7° bis (assurance chômage avec limite ministérielle). Le renvoi aux troisième à neuvième alinéas du 5° est conservé exactement ; dans la cible fournie, il couvre le principe dérogatoire et les a à f, sans déplacer les alinéas ni le confondre avec les frais de gestion. La suppression du CPF-CDD ne recrée aucune créance à affecter ; les autres réductions restent ouvertes aux futures situations éligibles. La date historique du 1er janvier 2024 n'est pas celle de la réforme.")

add('L226-1', '''
<p>L'autorité compétente de l'État nomme le directeur de chaque caisse nationale et celui de l'Agence centrale des organismes de sécurité sociale, après avis du président du conseil d'administration de l'organisme concerné. Les dispositions particulières des premier et deuxième alinéas de l'article L. 221-3-1 sont réservées.</p>
''',
    "Droit constant : l'autorité de nomination, la consultation du président et la réserve du régime spécial sont rendues explicites. La consultation donne à la gouvernance de l'organisme une intervention dans le choix de son directeur, sans instituer d'agrément économique ni de délai minimal. La conserver protège l'articulation entre direction et conseil ; aucun doublon de demande ou de pièces n'est prescrit ici.",
    "Les deux premiers alinéas de L. 221-3-1 ont été lus : opposition du conseil de la CNAM à la majorité des deux tiers à la nomination proposée, nomination par décret pour cinq ans et avis favorable aux deux tiers avant cessation anticipée. La réserve ne se limite pas à un avis individuel du président. La note source signale l'erreur matérielle de la loi du 13 août 2004 : L. 221-3-1, et non L. 222-3-1 ; le texte fourni porte déjà le bon renvoi. Aucun régime de contrat de travail ni préavis privé n'est substitué à ces fonctions.")

add('L227-1', '''
<p>I. - Dans le respect des lois de financement de la sécurité sociale, l'autorité compétente de l'État conclut, avec chacun des organismes suivants, une convention d'objectifs et de gestion qui comporte des engagements réciproques des signataires : la Caisse nationale de l'assurance maladie, la Caisse nationale d'assurance vieillesse, la Caisse nationale des allocations familiales, la Caisse nationale de solidarité pour l'autonomie et l'Agence centrale des organismes de sécurité sociale.</p>
<p>Pour les branches mentionnées à l'article L. 200-2 et les organismes de recouvrement, ces conventions fixent les objectifs pluriannuels de gestion, les moyens de fonctionnement dont ces branches et organismes disposent pour les atteindre et les actions que chaque signataire met en œuvre à cette fin.</p>
<p>Elles précisent :</p>
<p>1° Les objectifs de mise en œuvre des dispositions législatives et réglementaires qui régissent la gestion du risque, le service des prestations ou le recouvrement des cotisations et des impôts affectés ;</p>
<p>2° Les objectifs d'amélioration de la qualité du service aux usagers ;</p>
<p>2° bis Les objectifs d'amélioration de la productivité du réseau et de son organisation territoriale ou, pour la branche mentionnée au 5° de l'article L. 200-2, les objectifs d'amélioration de la coordination des acteurs des politiques en faveur de l'autonomie des personnes âgées et des personnes handicapées ;</p>
<p>3° Les objectifs de l'action sociale, de la prévention, de la lutte contre l'exclusion et du soutien à l'autonomie des personnes âgées et des personnes handicapées ;</p>
<p>4° Les règles de calcul et d'évolution des budgets de gestion et, s'il y a lieu, des budgets d'action sanitaire et sociale, de prévention et de soutien à l'autonomie des personnes âgées et des personnes handicapées ;</p>
<p>5° Le cas échéant, sauf pour la branche mentionnée au 5° de l'article L. 200-2, les conditions de constitution ou d'amélioration et d'évolution du réseau des caisses locales.</p>
<p>Ces conventions prévoient, lorsqu'il y a lieu, les indicateurs quantitatifs et qualitatifs associés aux objectifs.</p>
<p>Les conventions des branches mentionnées aux 1° et 3° de l'article L. 200-2 et celle des organismes du régime général chargés du recouvrement identifient les objectifs et les actions dédiés au service des prestations et au recouvrement des cotisations des travailleurs indépendants.</p>
<p>Elles fixent aussi :</p>
<p>1° Les conditions de conclusion d'avenants pendant leur exécution, notamment pour tenir compte des lois de financement de la sécurité sociale et des modifications importantes de la charge de travail des organismes résultant de l'évolution du cadre législatif et réglementaire ;</p>
<p>2° Le processus d'évaluation contradictoire des résultats au regard des objectifs fixés.</p>
<p>II. - Abrogé.</p>
<p>III. - Les signataires fixent la durée pluriannuelle de chaque convention, sans durée minimale de quatre ans.</p>
<p>Les conventions et les avenants qui les modifient sont transmis aux commissions parlementaires mentionnées à l'article LO. 111-9.</p>
<p>La suppression de la durée minimale s'applique aux conventions conclues ou renouvelées à compter de l'entrée en vigueur de la loi. Les conventions en cours conservent leur terme et leurs engagements ; les signataires peuvent en modifier la durée d'un commun accord par avenant sans être tenus par l'ancienne durée minimale.</p>
''',
    "Réforme de fond : retrait de la durée minimale légale de quatre ans, qui rigidifie le choix des signataires alors que la programmation pluriannuelle, les engagements et l'évaluation contradictoire suffisent à organiser la gestion. Droit constant pour les organismes, thèmes, budgets, indicateurs éventuels, travailleurs indépendants, avenants et information du Parlement. Aucune obligation de compte rendu de remplacement n'est ajoutée.",
    "Les I, II abrogé et III, les deux séries de subdivisions et les dix-sept alinéas initiaux de contenu sont conservés à leur place, avant une transition supplémentaire. Le 5° de L. 200-2 est l'autonomie ; la coordination des acteurs y remplace les objectifs territoriaux du réseau et l'exception du 5° du I demeure. Les 1° et 3° de L. 200-2 maintiennent leurs objectifs dédiés aux indépendants. L. 227-2 continue de régler les signatures, L. 227-3 rend seulement facultative la contractualisation locale. La transmission parlementaire, utile au contrôle des LFSS, subsiste ; aucune baisse de droits ou de moyens n'est déduite d'une convention plus courte. La note d'entrée en vigueur au 1er janvier 2021 reste historique.",
    ["L'obligation de conclure toute convention d'objectifs et de gestion pour au moins quatre ans est supprimée, sans instaurer un autre délai minimal chiffré."])

add('L227-2', '''
<p>Pour chaque organisme national, la convention d'objectifs et de gestion est signée par le président du conseil ou du conseil d'administration et par le directeur général ou le directeur. Pour la branche accidents du travail et maladies professionnelles, elle est signée par le président de la commission des accidents du travail et des maladies professionnelles et par le directeur général de la Caisse nationale de l'assurance maladie.</p>
''',
    "Droit constant : la règle générale de double signature et la règle propre à la branche accidents du travail et maladies professionnelles sont énoncées dans deux phrases. Les deux signatures traduisent les engagements de la gouvernance et de la direction ; elles ne constituent pas deux demandes ou deux agréments. Les retirer priverait l'une des composantes de sa participation à l'engagement de l'organisme.",
    "Le signataire de la branche AT-MP est le président de sa commission, non le président du conseil de la CNAM. Les alternatives conseil/conseil d'administration et directeur général/directeur sont maintenues. La suppression du minimum de quatre ans dans L. 227-1 ne modifie ni les signataires ni les engagements valablement souscrits. Aucune signature de contrat de travail ni durée d'emploi ne résulte de cette convention de gestion.")

add('L227-3', '''
<p>La mise en œuvre des conventions d'objectifs et de gestion des branches mentionnées aux 1° à 4° de l'article L. 200-2 peut être précisée par des contrats pluriannuels de gestion conclus entre, d'une part, chaque caisse nationale ou l'Agence centrale des organismes de sécurité sociale et, d'autre part, chacun de ses organismes régionaux ou locaux. La conclusion de ces contrats est facultative. Lorsqu'ils sont conclus, ils sont signés, pour l'organisme national, par le président du conseil ou du conseil d'administration ou, selon le cas, par le président de la commission des accidents du travail et des maladies professionnelles, et par le directeur général ; pour l'organisme régional ou local, ils sont signés par le président du conseil ou du conseil d'administration et par le directeur de l'organisme concerné.</p>
<p>Toutefois, pour les organismes de la branche maladie, ces contrats sont signés par le directeur général de la Caisse nationale de l'assurance maladie et par le directeur de l'organisme concerné.</p>
<p>Le caractère facultatif de ces contrats s'applique à compter de l'entrée en vigueur de la loi, y compris aux projets de contrat en cours. Aucun contrat ni document de substitution ne peut être exigé pour décliner les conventions visées au premier alinéa, y compris par une disposition réglementaire d'application. Les contrats déjà conclus, leurs engagements et les droits qui en résultent demeurent régis par leurs stipulations et les règles qui leur sont applicables. L'absence de contrat ne dispense pas d'exécuter les autres obligations légales et réglementaires ni les conventions d'objectifs et de gestion applicables.</p>
''',
    "Réforme de fond : suppression du second étage obligatoire de contractualisation avec chaque organisme régional ou local. Les contrats de déclinaison demeurent possibles, sans document obligatoire de remplacement ; leurs signatures et l'exception maladie restent définies. Les conventions nationales et les obligations de gestion conservent leur force. La réforme respecte les engagements déjà conclus et n'annule aucun droit financier acquis.",
    "Champ conservé : 1° à 4° de L. 200-2, sans extension de ce dispositif à la branche autonomie. La rédaction explicite le couple constitué de l'organisme national compétent et de ses propres organismes, sans imposer un contrat commun à toutes les caisses nationales et à l'agence. L. 221-3-1, alinéas relatifs à la signature et au contrôle des contrats, doit s'entendre des seuls contrats effectivement conclus ; ses pouvoirs généraux demeurent. Coordination identifiée, non réécrite ici : R. 211-1-2, septième alinéa de contenu, prescrit une négociation/signature et une présentation des orientations dans les trois mois de la convention ; retirer cette obligation et son délai pour les contrats nouveaux. Ses comptes rendus d'exécution ne doivent concerner que les contrats existants. D. 213-7 II 2° conserve sa mission de qualité du service, même en l'absence de contrat local. Ces textes ont été lus. La note du 1er janvier 2021 n'est pas une date de réforme.",
    ["L'obligation de conclure un contrat pluriannuel de gestion avec chacun des organismes régionaux ou locaux est supprimée pour l'avenir, sans contrat ni document imposé de substitution."])

add('L228-1', '''
<p>I. - L'Institut national de formation est une union nationale au sens de l'article L. 216-3. Sous réserve du présent chapitre, les dispositions du présent livre lui sont applicables.</p>
<p>II. - Dans le cadre de la politique définie par l'Union des caisses nationales de sécurité sociale, l'institut exerce les missions d'intérêt général suivantes :</p>
<p>1° Concevoir et mettre en œuvre les actions de formation et de perfectionnement des personnels des organismes de sécurité sociale mentionnés au présent livre, à l'exception de ceux mentionnés à l'article L. 123-3 ;</p>
<p>2° Dispenser des formations au personnel d'encadrement des organismes de sécurité sociale, sans préjudice de l'article L. 123-3 ;</p>
<p>3° Réaliser, pour les organismes du régime général, les formations institutionnelles spécifiques au service public de la sécurité sociale ;</p>
<p>4° Concevoir et délivrer toute autre offre de formation aux organismes du régime général, aux autres organismes de protection sociale et aux institutions ayant avec la sécurité sociale des sujets d'intérêt public commun.</p>
<p>III. - L'institut peut exercer la fonction de centrale d'achat au sens du code des marchés publics, pour le compte des organismes de sécurité sociale et de tout organisme employant des agents régis par les conventions collectives applicables au personnel des organismes de sécurité sociale.</p>
<p>Il peut aussi passer des accords-cadres selon les règles prévues à l'article L. 224-12.</p>
<p>IV. - Le financement de l'institut est assuré :</p>
<p>1° Par des fonds ou des dotations de l'Union des caisses nationales de sécurité sociale ou de toute autre caisse nationale du régime général ;</p>
<p>2° Par la rémunération des services rendus ;</p>
<p>3° Par toute autre source de financement.</p>
<p>V. - Un décret fixe les modalités d'application du présent chapitre. Il précise notamment le contrôle et la tutelle exercés par l'État et l'Union nationale des caisses de sécurité sociale, la composition et le fonctionnement du conseil d'administration de l'institut, ainsi que la nomination de son directeur et de son directeur comptable et financier.</p>
''',
    "Droit constant : statut, quatre missions, facultés de mutualisation des achats, trois sources de financement et habilitation réglementaire sont réécrits intégralement. La centrale d'achat et les accords-cadres sont des facultés favorables, non des démarches imposées aux bénéficiaires. Les retirer rendrait les achats moins mutualisables. La tutelle protège les financements sociaux ; l'article ne prescrit pas d'agrément supplémentaire propre à chaque formation ou achat à supprimer.",
    "L. 216-3, L. 123-3 et L. 224-12 ont été lus dans le corpus : union de services communs ; compétence de l'École nationale supérieure, avec ses exclusions et dérogations ; facultés de marchés et d'accords-cadres. Leur champ n'est pas fusionné. Deux anomalies préexistantes sont signalées sans correction silencieuse : référence au code des marchés publics au III, dont la concordance actuelle avec le droit de la commande publique n'est pas fournie ; dénomination 'Union nationale des caisses de sécurité sociale' au V, différente de 'Union des caisses nationales de sécurité sociale' aux II et IV. Aucun nouveau renvoi de concordance n'est inventé. Les dispositions réglementaires d'application restent distinctes, et aucune durée de formation n'est un terme d'emploi.",
    benefit="Les avantages possibles du III sont conservés pour les opérations futures : recours facultatif à la centrale d'achat pour les organismes sociaux et ceux employant des agents des conventions collectives visées, ainsi qu'aux accords-cadres de L. 224-12. Les fonds et dotations du IV restent disponibles selon leurs règles, sans condition ni autorisation nouvelle. L'offre de formation demeure ouverte à tous les destinataires du II ; l'exception et la réserve de L. 123-3 préservent le champ propre de l'École et ses dérogations. Le texte ne contient pas d'exonération fiscale à retirer.")

add('L231-1', '''
<p>I. - Le conseil et les conseils d'administration des caisses nationales et de l'Agence centrale mentionnés aux articles L. 221-3, L. 222-5, L. 223-3 et L. 225-3, ainsi que la commission mentionnée à l'article L. 221-5, comprennent un nombre égal de femmes et d'hommes. Lorsque le nombre de membres est impair, l'écart entre les femmes et les hommes ne peut dépasser un. Un décret en Conseil d'État fixe les modalités de désignation qui garantissent cette composition.</p>
<p>II. - Les collèges mentionnés aux 1°, 2°, 3°, 5° et 6° du II de l'article L. 223-7 comprennent un nombre égal de femmes et d'hommes, selon les modalités du I du présent article.</p>
''',
    "Droit constant : la composition paritaire, la tolérance d'un membre lorsque l'effectif est impair et les collèges concernés sont explicités. Ces règles protègent l'égalité d'accès aux responsabilités ; elles ne constituent pas une formalité répétée susceptible d'être supprimée sans atteindre cette protection. Aucun prélèvement, délai minimal ou déclaration autonome n'est imposé ici.",
    "Les renvois à L. 221-3 et L. 223-7 ont été confrontés à leurs sources et propositions jointes. Le II ne s'étend ni au 4° ni au 5° bis de L. 223-7. Le renvoi aux modalités du I conserve la tolérance d'un membre pour un collège impair. La note de l'ordonnance du 1er décembre 2021 renvoie aux conditions du 2° de son article 5 II : leur texte n'est pas joint, et aucune nouvelle transition de mandat n'en est déduite. Aucun motif de rupture, ancienneté d'emploi ou mandat limité à la durée d'un contrat de travail n'est ajouté.")

add('L231-3', '''
<p>I. - Chaque organisation qui a désigné un ou plusieurs représentants au conseil ou au conseil d'administration d'un organisme de sécurité sociale mentionné aux titres Ier et II du présent livre désigne autant de suppléants que de titulaires.</p>
<p>Les suppléants siègent en l'absence des titulaires et remplacent ceux dont le siège devient vacant. Le suppléant qui remplace un titulaire au conseil ou au conseil d'administration d'une caisse nationale est du même sexe que ce titulaire. Lorsqu'un siège de titulaire ou de suppléant devient vacant, l'organisation nationale concernée désigne un ou plusieurs nouveaux représentants. Ceux-ci siègent jusqu'au prochain renouvellement de l'ensemble des conseils et conseils d'administration.</p>
<p>II. - Les suppléants des représentants du personnel sont les candidats qui suivent immédiatement, sur chaque liste, le dernier candidat élu de cette liste.</p>
''',
    "Droit constant : la double formulation du nombre égal de titulaires et de suppléants est réunie au premier alinéa, sans retirer l'obligation. Les règles de remplacement, de sexe et de fin de mandat sont conservées. La suppléance permet la continuité de la représentation ; sa suppression ferait perdre des droits de participation. Aucun second dossier ou délai d'attente n'est prescrit par cet article.",
    "Les trois alinéas de contenu restent dans leurs I et II. La règle du même sexe concerne le remplacement d'un titulaire d'une caisse nationale, sans extension tacite à tous les organismes. Le nouveau représentant achève le cycle collectif, non un nouveau mandat complet. L. 221-3 I prévoit aussi titulaire, suppléant et remplacement pour la durée restant à courir : les dispositifs sont compatibles. La note de la loi du 4 août 2014 attache son application au premier renouvellement des instances nationales et de la commission visées après cette loi ; aucun mandat n'est recommencé à la date de la présente réécriture.")

add('L231-4', '''
<p>Lorsqu'un conseil ou un conseil d'administration d'un organisme du régime général de sécurité sociale est dissous au cours des quatre premières années suivant sa désignation, de nouveaux membres sont désignés pour achever le mandat restant à courir jusqu'au prochain renouvellement de l'ensemble des conseils ou conseils d'administration.</p>
''',
    "Droit constant : la désignation après dissolution est rattachée clairement au reliquat du mandat collectif. Elle assure le rétablissement d'une gouvernance représentative et ne crée pas une procédure d'autorisation redondante. La suppression de l'exclusion collective dans L. 231-5 facilite ces désignations sans supprimer la nécessité de pourvoir les sièges.",
    "La condition des quatre premières années et le terme fixé au renouvellement collectif sont conservés. D. 231-1, identifié dans le corpus, indique un mandat de quatre ans ; le présent texte n'en étend pas la durée et ne règle pas silencieusement les cas hors de sa fenêtre. Aucune dissolution ancienne n'est annulée par la modification de L. 231-5, et aucun ancien membre ne retrouve automatiquement son siège.")

add('L231-5', '''
<p>Le membre d'un conseil ou l'administrateur révoqué ne peut être désigné aux mêmes fonctions pendant quatre ans à compter de l'arrêté de révocation.</p>
<p>La dissolution d'un conseil ou d'un conseil d'administration ne fait pas, à elle seule, obstacle à la désignation de ses anciens membres aux mêmes fonctions.</p>
<p>La suppression de l'interdiction liée à la seule dissolution s'applique aux désignations intervenant à compter de l'entrée en vigueur de la loi, même si la dissolution est antérieure. Elle n'annule ni la dissolution ni les décisions de désignation déjà prises et ne rétablit aucun mandat. L'interdiction résultant d'une révocation individuelle demeure applicable selon le premier alinéa.</p>
''',
    "Réforme de fond : suppression de l'interdiction collective de nouvelle désignation pendant quatre ans après une dissolution, indépendamment de toute faute individuelle. La révocation individuelle conserve son délai de quatre ans, qui protège la probité et le fonctionnement des organismes. La transition ouvre les futures désignations sans reconstitution automatique de mandats ni disparition d'une révocation.",
    "Le premier alinéa conserve le point de départ à l'arrêté de révocation et les mêmes fonctions comme champ de l'interdiction. Le second retire seulement l'effet collectif attaché à la dissolution. L. 231-4 continue d'exiger de nouvelles désignations pour le reliquat du mandat. Les conditions et incompatibilités de L. 231-6 et L. 231-6-1 restent opposables ; une personne individuellement révoquée ne peut se prévaloir de la seule réforme de la dissolution pour écarter son interdiction.",
    ["L'interdiction de désigner pendant quatre ans tous les anciens membres d'un conseil dissous est supprimée lorsqu'elle repose sur la seule dissolution, sans révocation individuelle."])

add('L231-5-1', '''
<p>Des décrets précisent, lorsque cela est nécessaire, les modalités d'application des articles L. 221-3, L. 222-5, L. 223-3, L. 223-7 et L. 225-3.</p>
''',
    "Droit constant : l'habilitation réglementaire est formulée directement et reste limitée aux besoins d'application des cinq articles cités. Elle permet d'organiser les conseils sans créer elle-même une transmission, un agrément ou une contribution. La retirer ne supprimerait pas une charge déterminée et rendrait moins lisible la mise en œuvre des règles de représentation.",
    "Les cinq références sont conservées. L. 221-3 et L. 223-7 fournis ont été lus en entier, sources, notes et propositions ; leurs règles de composition et compétences ne sont pas assimilées à des contrats de travail. L. 225-3 est réécrit dans ce lot. La date du 14 mai 2022, fixée par le décret du 12 mai 2022 dans la limite du 30 juin 2022, est historique : elle n'est ni avancée ni réutilisée pour la réforme. Cette habilitation ne permet pas de rétablir par décret des conditions ou formalités que les dispositions législatives proposées suppriment.")

add('L231-6', '''
<p>À la date de leur nomination, les membres des conseils ou des conseils d'administration doivent être âgés d'au moins dix-huit ans. Ils ne doivent avoir fait l'objet ni d'une des condamnations mentionnées aux articles L. 6 et L. 7 du code électoral ni d'une condamnation à une peine correctionnelle prononcée en application du code de la sécurité sociale.</p>
<p>Aucune limite supérieure d'âge n'est applicable, y compris aux représentants des retraités désignés au titre des personnes qualifiées et aux membres du conseil de la caisse nationale mentionnée à l'article L. 223-7.</p>
<p>La suppression de la limite supérieure d'âge et de l'exclusion fondée sur une peine contraventionnelle prononcée en application du code de la sécurité sociale s'applique aux nominations intervenant à compter de l'entrée en vigueur de la loi, y compris lorsque la condamnation est antérieure. Elle ne rétablit aucun mandat et ne remet pas en cause les décisions de nomination antérieures. Les autres conditions du premier alinéa demeurent applicables.</p>
''',
    "Réforme de fond : suppression du plafond général de soixante-cinq ans et de l'exclusion automatique pendant cinq ans pour toute contravention sociale. Ces exclusions générales ne caractérisent pas à elles seules une incapacité à représenter les assurés ou un conflit d'intérêts. La majorité, les condamnations électorales visées et les peines correctionnelles sociales restent des garanties de capacité et de probité ; les incompatibilités de L. 231-6-1 demeurent distinctes. Les dérogations d'âge antérieures sont absorbées par une ouverture plus favorable pour tous.",
    "Le minimum de dix-huit ans se mesure toujours à la nomination. Les anciennes dispenses de plafond pour les représentants des retraités et, à la CNSA, pour les catégories hors 3° et représentants d'institutions du 6° n'ont plus à être sollicitées : aucun collège ne subit désormais de plafond supérieur. Les références L. 6 et L. 7 du code électoral sont reprises sans inventer leur contenu ; leur portée et leur état actuels ne sont pas établis par les pièces fournies et doivent être vérifiés dans ce code extérieur, notamment le renvoi ancien à L. 7. D. 231-4, R. 182-2, D. 213-7 et D. 325-3 ont été lus : leurs renvois doivent intégrer les conditions allégées, sans exigence de preuve d'un âge plafond ou d'absence de contravention. D. 221-42 exclut déjà la condition d'âge dans son champ spécial : cette dispense demeure, sans lui imposer le minimum de dix-huit ans par cette coordination.",
    ["La limite supérieure de soixante-cinq ans pour la nomination aux conseils et conseils d'administration est supprimée, sans maintien de ce plafond dans certains collèges.",
     "L'exclusion automatique à raison d'une peine contraventionnelle sociale prononcée dans les cinq années précédant la nomination est supprimée, les garanties pénales restantes demeurant distinctes."])

add('L231-6-1', '''
<p>Ne peuvent être désignées comme membres d'un conseil ou administrateurs, ou perdent leur mandat, les personnes suivantes :</p>
<p>1° Les assurés volontaires, les assurés personnels, les employeurs et les travailleurs indépendants qui n'ont pas satisfait à leurs obligations envers les organismes de recouvrement de sécurité sociale dont ils relèvent ;</p>
<p>2° Les membres du personnel des organismes du régime général de sécurité sociale, de leurs unions, fédérations ou établissements, ainsi que leurs anciens membres qui ont cessé leur activité depuis moins de cinq ans et exerçaient une fonction de direction dans la branche pour laquelle ils sollicitent un mandat ;</p>
<p>3° Au conseil d'une caisse primaire d'assurance maladie, les agents des sections locales de cette caisse qui assurent une partie de ses attributions ;</p>
<p>4° Les agents qui, dans leurs attributions, exercent effectivement des fonctions de contrôle ou de tutelle sur l'organisme concerné ou ont cessé de les exercer depuis moins de cinq ans ;</p>
<p>5° Dans le ressort de l'organisme de sécurité sociale :</p>
<p>a) Pour la Caisse nationale de l'assurance maladie, les caisses d'assurance retraite et de la santé au travail et les caisses primaires d'assurance maladie :</p>
<p>- les personnes exerçant des fonctions de direction dans un établissement public de santé, ou des fonctions de direction ou un mandat d'administrateur dans un établissement de santé privé à but lucratif ou non lucratif ;</p>
<p>- les personnes produisant, offrant ou délivrant des soins, des biens ou des services médicaux pris en charge par l'assurance maladie, ainsi que les mandataires d'organisations représentant leurs professions ;</p>
<p>b) Les personnes, salariées ou non, exerçant les fonctions d'administrateur, de directeur ou de gérant d'une entreprise, institution ou association à but lucratif, qui bénéficient d'un concours financier de la part de l'organisme de sécurité sociale, ou qui participent à la prestation de travaux, de fournitures ou de services ou à l'exécution de contrats d'assurance, de bail ou de location ;</p>
<p>c) Les personnes percevant, à quelque titre que ce soit, des honoraires d'un organisme du régime général de sécurité sociale ;</p>
<p>d) Les personnes qui, dans leur activité professionnelle, plaident ou consultent pour ou contre l'organisme où elles siègent, ou effectuent des expertises pour l'application de la législation de sécurité sociale à ses ressortissants.</p>
<p>Le b du 5° ne s'applique pas aux membres des collèges mentionnés aux 1°, 3° et 6° du II de l'article L. 223-7.</p>
<p>Perdent aussi leur mandat :</p>
<p>1° Les personnes qui cessent d'appartenir à l'organisation qui les a désignées au sein d'un conseil ou d'un conseil d'administration ;</p>
<p>2° Les personnes dont l'organisation qui les a désignées demande le remplacement.</p>
<p>L'exclusion fondée sur un licenciement pour motif disciplinaire intervenu depuis moins de dix ans est supprimée pour les désignations et l'exercice des mandats à compter de l'entrée en vigueur de la loi. Un tel licenciement ne peut, à lui seul, empêcher une désignation ou entraîner la perte d'un mandat après cette date. Cette suppression n'annule pas les décisions antérieures de cessation de mandat et ne rétablit aucun mandat. Les autres incompatibilités et causes de perte du mandat prévues au présent article demeurent applicables.</p>
''',
    "Réforme de fond : retrait de l'exclusion générale de dix ans fondée sur tout licenciement disciplinaire, sans appréciation d'un conflit actuel. Cette sanction professionnelle ne justifie pas à elle seule une interdiction de représentation aussi longue. Les incompatibilités liées aux fonctions en cours, aux anciennes fonctions de direction ou de contrôle durant cinq ans, aux prestations financées et aux intérêts professionnels demeurent. Droit constant pour les autres cas et pour la dérogation favorable propre à certains collèges de la CNSA.",
    "Les deux séries de 1° et 2°, les 3°, 4°, 5° a à d et les deux tirets du a sont conservés à leur place. Les deux délais de cinq ans demeurent distincts : ancienne direction dans la branche sollicitée ; ancien contrôle ou tutelle sur l'organisme. La suppression du délai disciplinaire de dix ans ne supprime ni ces incompatibilités ni les conditions pénales de L. 231-6. La dérogation au b du 5° reste ouverte aux futures désignations des collèges 1°, 3° et 6° du II de L. 223-7 ; elle ne dispense pas des autres a, c ou d. D. 231-4 et les renvois de R. 182-2, D. 213-7 et D. 325-3, lus dans le corpus, doivent cesser de demander les informations exclusivement nécessaires à l'ancienne exclusion disciplinaire. La note du 14 mai 2022 conserve son objet historique.",
    ["L'interdiction de désignation et la perte automatique du mandat fondées sur tout licenciement disciplinaire depuis moins de dix ans sont supprimées, sans retirer les autres incompatibilités."])

add('L231-7', '''
<p>Les membres de chaque conseil ou conseil d'administration des caisses locales et des organismes nationaux du régime général de sécurité sociale élisent leur président et, lorsqu'il y a lieu, leur ou leurs vice-présidents.</p>
<p>Les personnes qualifiées ne prennent pas part au vote pour ces élections et ne sont pas éligibles à ces fonctions.</p>
<p>Dans un organisme régional ou local issu de la fusion d'au moins deux organismes, ne peut être élu président un membre qui a déjà exercé deux fois cette fonction dans l'un des conseils ou conseils d'administration des organismes fusionnés.</p>
<p>Le deuxième alinéa ne s'applique pas à la Caisse nationale de solidarité pour l'autonomie.</p>
''',
    "Droit constant : l'élection, la restriction concernant les personnes qualifiées, la règle de continuité des mandats après fusion et l'exception CNSA sont réécrites dans leurs quatre alinéas. Ces règles préservent le choix des représentants et empêchent de remettre à zéro la limite de présidence par une fusion. L'exception favorable de la CNSA demeure ouverte ; elle est cohérente avec la désignation de son président parmi les personnalités qualifiées. Aucun agrément ou délai additionnel n'est ajouté.",
    "L'exclusion du vote concerne les seules élections aux fonctions de président et vice-président, sans supprimer le vote des personnes qualifiées sur les autres affaires du conseil. L'exception vise exactement le deuxième alinéa, non la règle de fusion du troisième. Les deux exercices antérieurs s'apprécient dans l'un des organismes fusionnés, sans ajouter de condition de consécutivité. La note d'application au 14 mai 2022 ne sert pas de nouvelle transition. Les dispositions du III de L. 223-7 concernant les compétences de la CNSA ne sont pas modifiées par cette règle électorale.")

add('L231-8', '''
<p>Le conseil ou le conseil d'administration d'une caisse siège valablement lorsque le nombre de ses membres siégeant est strictement supérieur à la moitié du nombre total de membres qui le composent.</p>
''',
    "Droit constant : le seuil strictement supérieur à la moitié est exprimé comme une règle de quorum. Il protège la réalité de la décision collégiale ; sa suppression permettrait une décision par une minorité sans règle alternative justifiée. Aucun délai d'attente ou document supplémentaire n'est imposé par cet article.",
    "Le texte source parle du 'nombre de ses membres' sans préciser expressément 'siégeant' : cette imprécision préexistante est signalée. La proposition explicite sa lecture comme quorum sans modifier le dénominateur ni autoriser une seconde réunion sans quorum. Elle ne tranche pas les régimes distincts de procuration, de voix consultative ou de participation à distance ; leurs règles d'application doivent rester compatibles avec le seuil légal, sans présumer ici leur contenu.")

add('L231-8-1', '''
<p>Le conseil d'administration règle par délibération les affaires de l'organisme, sauf celles que lui-même ou les caisses nationales ont déléguées à une union ou à un groupement d'organismes.</p>
<p>Le conseil ou le conseil d'administration oriente et contrôle l'activité de la caisse. Il se prononce notamment sur les rapports que lui soumet le directeur dans les conditions fixées par décret en Conseil d'État. Les relations avec les usagers font l'objet d'un rapport ; l'action sanitaire et sociale fait également l'objet d'un rapport, sauf dans les unions de recouvrement des cotisations de sécurité sociale et d'allocations familiales et à la Caisse nationale de solidarité pour l'autonomie. Ces rapports peuvent être réunis dans un même document, avec des parties identifiables, ou intégrés dans un rapport existant qui comporte ces parties. Leur présentation dans des documents distincts ne peut être imposée. Au moins une séance annuelle du conseil ou du conseil d'administration est consacrée aux relations de la caisse avec les usagers ; cette séance est publique.</p>
<p>Le conseil ou le conseil d'administration peut entendre toute personne ou organisation utile à son action. Le conseil d'une caisse primaire d'assurance maladie entend les représentants des professions de santé lorsque cela est utile à l'exercice de ses attributions, sans nombre minimal annuel d'auditions.</p>
<p>La dispense de documents distincts et la suppression du nombre minimal d'auditions s'appliquent à compter de l'entrée en vigueur de la loi, y compris aux rapports et auditions restant à organiser pour des périodes antérieures. Aucun rapport déjà présenté n'est à refaire et aucune audition de rattrapage n'est exigée sur le seul fondement de l'ancienne fréquence minimale. Les autres droits de consultation et obligations légales d'information demeurent applicables.</p>
''',
    "Réforme de fond : suppression de l'exigence de rapports matériellement séparés et du minimum de deux auditions annuelles des professions de santé. Les thèmes de contrôle restent obligatoires, mais un document existant peut les accueillir ; les auditions sont commandées par leur utilité. La séance annuelle publique consacrée aux usagers, les compétences du conseil, les délégations et les exemptions propres aux URSSAF et à la CNSA sont maintenues.",
    "Le deuxième alinéa conserve les deux thèmes et l'exception limitée à l'action sanitaire et sociale pour les URSSAF et la CNSA. La publicité et le minimum d'une séance annuelle sur les usagers ne sont pas supprimés ; leur fonction de transparence est distincte de la répétition documentaire. R. 211-1-2 a été lu : son rapport d'activité et de fonctionnement présenté au plus tard à la fin du premier semestre peut recevoir les parties requises ; sa transmission et ses autres objets autonomes ne sont pas abrogés ici. Coordonner les textes d'application de L. 231-8-1 sans rétablir deux documents obligatoires ni deux auditions automatiques. La présente suppression de fréquence n'abolit pas les réunions périodiques autonomes des conseils, notamment celles prévues par R. 231-1, qui ne sont pas réécrites dans ce lot.",
    ["La production de documents obligatoirement distincts pour les rapports sur les usagers et sur l'action sanitaire et sociale est écartée au profit de parties identifiables dans un document commun ou existant.",
     "Le minimum imposé de deux auditions par an des représentants des professions de santé devant le conseil de chaque caisse primaire est supprimé, sans retirer la faculté d'audition utile."])

add('L231-9', '''
<p>L'employeur laisse au salarié de son entreprise qui est membre du conseil ou du conseil d'administration d'un organisme de sécurité sociale le temps nécessaire pour se rendre aux séances plénières de ce conseil et aux séances de ses commissions, et pour y participer.</p>
<p>Le temps que ce salarié passe hors de l'entreprise pendant ses heures de travail pour exercer ces fonctions est assimilé à du travail effectif pour déterminer la durée des congés payés, le droit aux prestations d'assurances sociales et aux prestations familiales, ainsi que tous les droits liés à son ancienneté dans l'entreprise.</p>
<p>Les absences justifiées par l'exercice de ces fonctions n'entraînent aucune diminution de la rémunération ni des avantages qui s'y rattachent.</p>
<p>Le salarié membre d'un conseil ou administrateur qui travaille en service continu ou discontinu posté a droit à un aménagement de ses horaires de travail lui garantissant un temps de repos minimum.</p>
<p>Un décret fixe les modalités d'indemnisation des salariés qui travaillent en dehors de tout établissement ou dépendent de plusieurs employeurs.</p>
''',
    "Droit constant : les cinq garanties d'exercice du mandat sont réécrites intégralement. Le déplacement, la participation, les assimilations pour les droits sociaux, la rémunération, le repos et l'indemnisation des salariés atypiques restent protégés. Retirer l'obligation patronale ferait disparaître un droit favorable et compromettrait la représentation ; il ne s'agit pas d'une formalité accessoire à supprimer.",
    "L'assimilation reste limitée aux objets légaux énumérés, sans création d'une majoration générale d'heures supplémentaires. Le maintien de rémunération couvre aussi les avantages afférents. Aucun nouveau préavis de demande ni justificatif périodique n'est ajouté. Les absences de mandat restent comprises dans les droits liés à l'ancienneté, y compris pour les contrats uniques futurs selon leurs règles de rupture ; aucune première année n'est retranchée et aucune indemnité ordinaire n'est supprimée ici. Les droits des anciens contrats demeurent, ainsi que le champ des salariés hors établissement ou multiemployeurs.")

add('L231-10', '''
<p>À la demande d'un salarié de son entreprise qui est membre du conseil ou du conseil d'administration d'un organisme de sécurité sociale, l'employeur lui accorde les autorisations d'absence nécessaires pour assister aux sessions de formation organisées pour l'exercice de ses fonctions.</p>
<p>Dans les conditions fixées par décret, les organismes de sécurité sociale peuvent financer la formation des membres des conseils ou conseils d'administration des organismes de sécurité sociale afin de les préparer à l'exercice de leurs fonctions.</p>
''',
    "Droit constant : le droit à autorisation d'absence sur demande et la faculté de financement sont exprimés directement. L'autorisation est ici une garantie que l'employeur doit accorder au salarié, et non un agrément administratif d'activité ; la supprimer retirerait un avantage. Aucun délai minimal de demande, pièce répétée ou validation supplémentaire n'est créé.",
    "Deux alinéas conservés : obligation de l'employeur sur demande, financement seulement facultatif par les organismes dans les conditions réglementaires. Le texte n'institue pas à lui seul un maintien de salaire supplémentaire pour la formation au-delà des règles applicables. La durée d'une session ou du mandat n'est pas la durée du contrat de travail : l'accès des salariés sous contrat unique et celui des anciens contrats reste ouvert selon les mêmes conditions de mandat.")

add('L231-12', '''
<p>Les organismes de sécurité sociale ne peuvent en aucun cas verser un traitement aux membres de leurs conseils ou à leurs administrateurs. Ils leur remboursent toutefois leurs frais de déplacement.</p>
<p>Ils remboursent aussi aux employeurs des membres de conseil ou administrateurs salariés les salaires maintenus pour l'exercice des fonctions de ces derniers pendant le temps de travail, ainsi que les avantages et les charges sociales correspondants.</p>
<p>Les membres d'un conseil ou administrateurs qui sont travailleurs indépendants peuvent percevoir des indemnités pour perte de gains, dont le montant est fixé par arrêté ministériel.</p>
''',
    "Droit constant : la distinction entre traitement interdit, remboursements obligatoires et indemnisation possible des indépendants est conservée. Les remboursements allègent le coût du mandat pour les personnes et les employeurs ; les retirer irait contre la préservation des avantages. L'interdiction d'un traitement prévient la transformation du mandat en emploi rémunéré et n'interdit aucune des indemnités expressément permises.",
    "Les trois alinéas et leurs objets restent à leur place. Les charges sociales afférentes aux salaires maintenus restent remboursables ; elles ne sont pas une taxe autonome créée par cet article. Aucun plafond d'indemnité ordinaire de rupture, seuil d'un an ou préavis de quinze jours ne s'applique à ces remboursements. La faculté d'indemniser la perte de gains des indépendants reste ouverte aux futurs mandats. R. 231-6, identifié dans le corpus, attribue l'arrêté du troisième alinéa au ministre chargé de la sécurité sociale ; aucun montant n'est inventé.")

add('L231-13', '''
<p>Des décrets précisent, lorsque cela est nécessaire, les modalités d'application des articles L. 231-2 à L. 231-4 et L. 231-6 à L. 231-8.</p>
''',
    "Droit constant pour l'habilitation : les deux plages de références sont conservées. Cette disposition ne prescrit elle-même aucune formalité ou contribution. Les décrets doivent appliquer les conditions législatives allégées de L. 231-6 et L. 231-6-1, sans recréer les exclusions supprimées ; la suppression de l'habilitation ne suffirait pas à supprimer ces charges et compliquerait l'organisation des conseils.",
    "Les plages comprennent L. 231-6-1 mais non L. 231-5, L. 231-8-1 ou les droits des articles suivants. Le numéro L. 231-2, présent dans la source de l'habilitation, n'a pas été trouvé comme article autonome dans l'édition du corpus fournie : ce renvoi ancien est signalé, sans inventer son contenu ni prétendre le remettre en vigueur. La référence est laissée pour contrôle de concordance. Les dispositions réglementaires ne peuvent imposer à nouveau le plafond de soixante-cinq ans, l'exclusion de cinq ans pour contravention sociale ou celle de dix ans pour licenciement disciplinaire retirés par les articles réécrits de ce lot.")


# La construction du b est conservée faute de concordance levant son ambiguïté.
next(a for a in answers if a['number'] == 'L231-6-1')['review_notes'] += " Le b du 5° présente une ambiguïté grammaticale préexistante : les relatifs au pluriel suivent une liste d'entités au singulier. Sa construction est conservée pour ne pas décider silencieusement si les concours et prestations se rattachent aux personnes ou aux entités administrées ; ce point de portée reste à contrôler, sans nouvelle exclusion."

# Les analyses ci-dessous distinguent les règles officielles et les propositions
# fournies. Une cible requise peut être sans effet sur le mandat social examiné.
checks = {
    'L225-6': {
        'L1234-1': "L. 225-6 affecte des soldes de compensation et ne renvoie pas au préavis du salarié. La proposition de L. 1234-1 vise quinze jours pour les nouveaux contrats et réserve les anciens préavis ; aucune de ces durées ne conditionne la répartition entre branches ni ne remplace une procédure collective.",
        'L1221-2': "Le contrat unique concerne les nouvelles relations d'emploi privé, non la durée de l'affectation d'un solde entre organismes. Les compensations des 7° et 7° bis de L. 225-1-1 restent attachées aux réductions éligibles futures ; le renvoi financier de L. 225-6 ne doit ni rétablir de CDD ni réserver ces réductions aux anciens contrats.",
        'L1234-9': "Le seuil d'un an à la fin effective du contrat, préavis inclus, et le calcul de 0,20 mois sur toute l'ancienneté, au prorata des mois complets et plafonné à six mois, règlent une indemnité patronale de rupture. Ils sont sans objet pour les soldes de L. 225-6 ; les droits des anciens contrats et indemnités spéciales ne sont pas touchés par cette affectation.",
        'L225-1-1': "Les renvois du II portent précisément sur les 7° bis, 7° et troisième à neuvième alinéas du 5°, non sur un contrat à durée déterminée. Les sources et propositions conservent deux compensations distinctes. La suppression prospective du CPF-CDD dans la proposition cible ne laisse aucune recette fictive à répartir ; les réductions éligibles futures et les opérations antérieures gardent leurs champs et limites."
    },
    'L231-1': {
        'L1234-1': "L. 231-1 règle la composition paritaire d'instances et ne contient aucun renvoi au licenciement. Les quinze jours calendaires du nouveau contrat et les préavis préservés des anciens contrats n'ont aucun effet sur le nombre de femmes et d'hommes ni sur la durée du mandat ; aucune procédure de protection du salarié n'est remplacée.",
        'L1221-2': "La désignation au conseil n'est pas une nouvelle embauche. Ni le renvoi à L. 221-3 ni celui au II de L. 223-7 ne permet de transformer un mandat ou un contrat de travail transféré en nouveau CDD. L'accès paritaire reste applicable indépendamment de l'ancien ou du nouveau régime d'emploi de la personne désignée.",
        'L1234-9': "Aucune indemnité ordinaire de licenciement n'est fixée dans L. 231-1. Le seuil d'un an, préavis compris, et la formule de 0,20 mois par année totale avec prorata des mois complets et plafond de six mois concernent la rupture patronale du contrat unique, sans conditionner les désignations ni retirer les droits des anciens contrats.",
        'L221-3': "Le I de L. 231-1 vise le conseil de la CNAM défini au I de L. 221-3, pas ses règles de gestion du II. La proposition cible conserve les catégories et remplace la référence au deuxième alinéa par le 1° pour la majorité. Les transferts d'emploi de 2018-2019 et leur exemption de taxes dans les notes restent anciens ; ils ne déclenchent pas un contrat unique nouveau.",
        'L223-7': "Le II de L. 231-1 vise exactement les collèges 1°, 2°, 3°, 5° et 6° du II de L. 223-7. Ni le collège de l'État du 4° ni celui des régimes du 5° bis n'y est ajouté. La suppression proposée de l'arrêté de nomination du président ne modifie pas ces assiettes de parité et ne touche à aucune relation d'emploi privé."
    },
    'L231-3': {
        'L1234-1': "L'absence, la vacance et le renouvellement d'un siège de conseil ne sont pas une rupture de contrat de travail. Les durées de préavis de L. 1234-1, quinze jours proposés pour les nouveaux contrats ou anciennes durées préservées, ne fixent donc ni un délai de remplacement ni le terme du mandat de suppléant.",
        'L1221-2': "Le remplacement d'un titulaire par un suppléant ne constitue pas une embauche ni un renouvellement de CDD. Le mandat finit au renouvellement collectif, alors que la relation d'emploi nouveau demeure indéterminée. Les anciens contrats, notamment transférés dans le cadre étudiant de la note de L. 221-3, gardent leur transition propre.",
        'L1234-9': "L. 231-3 ne règle aucune indemnité de licenciement. La durée restant à courir d'un mandat ne se substitue ni à l'ancienneté d'emploi ni au seuil d'un an, préavis inclus, de la proposition L. 1234-9 ; elle ne modifie pas son calcul sur l'ancienneté totale, le prorata des mois complets, le plafond ou les anciens droits.",
        'L221-3': "Le I de L. 221-3 prévoit un titulaire et un suppléant par siège des organisations et institutions des 1°, 2°, 3° et 5°, avec remplacement jusqu'au terme restant. L. 231-3 conserve cette logique, ajoute le remplacement de même sexe pour le titulaire national et règle séparément la suite des listes du personnel, sans déplacer les catégories de la cible."
    },
    'L231-5-1': {
        'L1234-1': "L'habilitation de L. 231-5-1 porte sur l'organisation des conseils des cinq articles cités, pas sur le préavis d'un salarié. Elle n'autorise ni à imposer quinze jours de préavis à un mandat ni à supprimer les anciennes règles de contrats, les procédures collectives ou les autorisations protectrices applicables à une rupture d'emploi.",
        'L1221-2': "Les décrets d'application de la composition des organismes ne peuvent créer un contrat de travail à terme ni assimiler la nomination ou la fin d'un mandat à une embauche. La règle des nouveaux emplois privés indéterminés et les transitions des contrats anciens restent extérieures au champ de cette habilitation institutionnelle.",
        'L1234-9': "Le pouvoir d'application des cinq articles de gouvernance ne concerne aucune indemnité patronale de licenciement. Il ne peut modifier le seuil d'un an en fin effective avec préavis, le taux de 0,20 mois, le calcul sur l'ancienneté totale par mois complets, le plafond de six mois ou les composantes antérieures protégées par la proposition cible.",
        'L221-3': "Le renvoi de L. 231-5-1 conserve l'ensemble de L. 221-3 : composition au I, compétences et fonctionnement au II, mise en œuvre au III. La proposition cible retire la fréquence trimestrielle obligatoire mais garde les convocations de droit ; l'habilitation ne permet pas de la rétablir. Les transferts d'emploi historiques de la note sont distincts d'une désignation actuelle.",
        'L223-7': "L. 231-5-1 habilite les modalités d'application de L. 223-7, dont le II règle composition et présidence de la CNSA et les IV et V la direction et le conseil scientifique. La proposition cible supprime un arrêté présidentiel et les pièces répétées : l'habilitation ne les recrée pas. La nomination publique du directeur reste distincte du contrat de travail privé."
    },
    'L231-6': {
        'L1234-1': "La date de nomination à un conseil sert à vérifier capacité et condamnations, sans lien avec la notification d'un licenciement. La suppression du plafond d'âge ne modifie ni les quinze jours proposés pour le contrat unique ni les préavis des contrats anciens, et ne dispense d'aucune autorisation protectrice d'une rupture d'emploi.",
        'L1221-2': "L'ouverture de la désignation au-delà de soixante-cinq ans porte sur un mandat, non sur un contrat d'emploi nouveau. Le renvoi à la CNSA ne crée donc aucun CDD spécial ni terme automatique à l'âge ou à la fin du mandat ; les contrats de travail anciens ou futurs suivent séparément leurs règles et transitions.",
        'L1234-9': "Les dix-huit ans de L. 231-6 sont un âge civil à la nomination, non un seuil d'ancienneté. L'allègement de l'éligibilité ne modifie pas le seuil d'un an à la fin effective du contrat, préavis inclus, ni l'indemnité patronale de 0,20 mois par année totale avec mois complets et plafond de six mois ; les anciens droits restent distincts.",
        'L223-7': "La source de L. 231-6 limitait le plafond de soixante-cinq ans à tout le 3° et aux représentants d'institutions du 6° du conseil défini au II de L. 223-7, pas à toutes les personnalités qualifiées. Le plafond est supprimé pour tous, ce qui conserve et étend les anciennes dispenses. La nomination par décret du directeur au IV n'est pas convertie en emploi privé."
    },
    'L231-6-1': {
        'L1234-1': "La perte d'un mandat pour incompatibilité n'est pas le licenciement d'un salarié. Le préavis de quinze jours du nouveau contrat proposé et les préavis antérieurs ne règlent pas cette perte ; inversement, supprimer l'exclusion liée à l'ancien licenciement disciplinaire ne dispense l'employeur d'aucune notification, protection ou procédure de rupture.",
        'L1221-2': "La suppression d'une inéligibilité après licenciement disciplinaire ne transforme ni l'ancien emploi ni le mandat actuel en contrat unique nouveau. Les incompatibilités de personnel actuel restent applicables. La durée limitée d'un mandat ou une mission de contrôle ne crée aucun contrat de travail à terme dans le régime des embauches futures.",
        'L1234-9': "Le délai disciplinaire de dix ans supprimé concerne l'accès au mandat ; il n'est ni un seuil d'ancienneté ni une indemnité. La proposition L. 1234-9 conserve son champ de rupture patronale, son seuil d'un an préavis inclus, son calcul de 0,20 mois sur l'ancienneté totale avec mois complets et plafond de six mois, ainsi que les anciens droits et indemnités spéciales.",
        'L223-7': "La dérogation de L. 231-6-1 vise seulement le b du 5° pour les membres des collèges 1°, 3° et 6° du II de L. 223-7. Elle demeure pour les futurs mandats, sans être limitée aux personnes déjà en fonction. Les autres incompatibilités du 5° et les délais autonomes de cinq ans restent distincts ; la proposition cible ne crée pas de nouveau contrat de travail à terme."
    },
    'L231-12': {
        'L1234-1': "Les salaires maintenus puis remboursés à l'employeur correspondent au temps de mandat pendant le travail. Ils ne sont pas une indemnité compensatrice de préavis : ni les quinze jours proposés pour les nouveaux contrats ni les anciennes durées de L. 1234-1 ne limitent le remboursement ou les frais de déplacement.",
        'L1221-2': "Le mandat social non rémunéré par un traitement n'est pas un emploi à durée déterminée. Les remboursements restent ouverts lorsque le salarié relève du contrat unique futur comme lorsqu'il conserve un ancien contrat ; la durée du mandat ne termine pas son emploi. L'indemnisation des indépendants conserve son régime distinct.",
        'L1234-9': "Les remboursements de frais et salaires et les indemnités de perte de gains ne sont pas l'indemnité ordinaire de rupture patronale. Le seuil d'un an en fin effective avec préavis et le barème proposé de 0,20 mois par année totale, mois complets et plafond de six mois ne leur sont pas applicables ; aucune franchise ou plafond de rupture n'est importé dans L. 231-12."
    }
}

targets_by_number = {v['number']: (k, v) for k, v in references['targets'].items()}
for obj in answers:
    key = obj['code_id'] + '|' + obj['source_id']
    required = references['requirements'].get(key, [])
    if required:
        result = []
        for target_key in required:
            target = references['targets'][target_key]
            assessment = checks[obj['number']][target['number']]
            result.append(dict(target_key=target_key, view_sha256=target['view_sha256'], assessment=assessment))
        obj['reference_checks'] = result

assert [a['number'] for a in answers] == [s['number'] for s in sources]
assert len(answers) == 24
Path('answer.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n')
